BEGIN;
DO $$
DECLARE
  v_subject_id UUID;
  v_topic_id UUID;
  v_test_id BIGINT;
BEGIN
  SELECT id INTO v_subject_id FROM test_subjects WHERE name ILIKE '%cardio%' ORDER BY id LIMIT 1;
  IF v_subject_id IS NULL THEN
    INSERT INTO test_subjects (name, description) VALUES ('Cardiovascular System', 'Cardiovascular notes') RETURNING id INTO v_subject_id;
  END IF;
  SELECT id INTO v_topic_id FROM test_topics WHERE name = 'PVD / PAD / DVT' ORDER BY (SELECT COUNT(*) FROM test_questions q WHERE q.topic_id = test_topics.id) DESC, created_at ASC LIMIT 1;
  IF v_topic_id IS NULL THEN
    INSERT INTO test_topics (subject_id, name, description, status) VALUES (v_subject_id, 'PVD / PAD / DVT', 'Peripheral vascular disorders comparison and management', 'published') RETURNING id INTO v_topic_id;
  END IF;
  SELECT id INTO v_test_id FROM tests WHERE is_active = true ORDER BY id LIMIT 1;
  IF v_test_id IS NULL THEN
    INSERT INTO tests (test_name, system_category, description, is_active)
    VALUES ('Cardiovascular System - PVD/PAD/DVT (Generated)', 'Cardiovascular System', 'Auto-generated NCLEX question set', true)
    RETURNING id INTO v_test_id;
  END IF;
  DELETE FROM test_questions WHERE topic_id = v_topic_id AND category = 'PVD PAD DVT - NCLEX';
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "PVD umbrella concept" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "PVD umbrella concept" is most accurate?', '[{"id": "a", "text": "Peripheral vascular disease is an umbrella term that includes arterial and/or venous disorders."}, {"id": "b", "text": "PVD includes only pulmonary vessels in this note."}, {"id": "c", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "d", "text": "ABI >1.5 confirms PAD in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Peripheral vascular disease is an umbrella term that includes arterial and/or venous disorders. Differentiate arterial from venous findings before intervention.', 'PVD PAD DVT - NCLEX', false, 1, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "PAD definition" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "PAD definition" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "Recognize ischemic limb signs and perfusion threats early."}, {"id": "b", "text": "PAD is caused by pulmonary emboli in this note."}, {"id": "c", "text": "PAD is venous valve failure in this note."}, {"id": "d", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}]'::jsonb, '["a"]'::jsonb, 'Correct because Peripheral arterial disease is arterial narrowing from atherosclerosis causing reduced blood flow. Recognize ischemic limb signs and perfusion threats early.', 'PVD PAD DVT - NCLEX', false, 2, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "DVT definition" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "DVT definition" in PVD / PAD / DVT?', '[{"id": "a", "text": "DVT has no embolic risk in this note."}, {"id": "b", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "c", "text": "Buerger test confirms DVT in this note."}, {"id": "d", "text": "Deep vein thrombosis is thrombus formation in deep veins, usually leg, with pulmonary embolism risk."}]'::jsonb, '["d"]'::jsonb, 'Correct because Deep vein thrombosis is thrombus formation in deep veins, usually leg, with pulmonary embolism risk. Prevent embolization and monitor for PE deterioration.', 'PVD PAD DVT - NCLEX', false, 3, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Venous insufficiency signs" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "Venous insufficiency signs" in PVD / PAD / DVT?', '[{"id": "a", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "b", "text": "Cool hairless skin is classic venous profile in this note."}, {"id": "c", "text": "Use skin temperature/pulse pattern to separate venous from arterial disease."}, {"id": "d", "text": "Absent pulses are hallmark venous insufficiency sign in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Venous insufficiency signs include varicosities, edema, brown hemosiderin skin changes, warm moist skin, and pulses present. Use skin temperature/pulse pattern to separate venous from arterial disease.', 'PVD PAD DVT - NCLEX', false, 4, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Venous stasis ulcer profile" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "Venous stasis ulcer profile" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "b", "text": "Venous ulcers are punched-out lateral toe lesions in this note."}, {"id": "c", "text": "Hypothermia is a Virchow component in this note."}, {"id": "d", "text": "Venous ulcers are usually at medial malleolus, irregular edges, and often painless."}]'::jsonb, '["d"]'::jsonb, 'Correct because Venous ulcers are usually at medial malleolus, irregular edges, and often painless. Correct ulcer classification guides positioning and wound strategy.', 'PVD PAD DVT - NCLEX', false, 5, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "PAD symptom hallmark" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "PAD symptom hallmark" is most accurate?', '[{"id": "a", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "b", "text": "Frequent ambulation is stasis cause in this note."}, {"id": "c", "text": "Progression from exertional pain to rest pain signals worsening ischemia."}, {"id": "d", "text": "PAD pain improves with walking in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Intermittent claudication is leg pain with walking relieved by rest; advanced disease may cause rest pain. Progression from exertional pain to rest pain signals worsening ischemia.', 'PVD PAD DVT - NCLEX', false, 6, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "ABI threshold" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "ABI threshold" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "Ankle-brachial index below 0.9 supports PAD diagnosis."}, {"id": "b", "text": "Cancer lowers DVT risk in this note."}, {"id": "c", "text": "ABI is not used for PAD in this note."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["a"]'::jsonb, 'Correct because Ankle-brachial index below 0.9 supports PAD diagnosis. Use ABI to quantify arterial perfusion deficit objectively.', 'PVD PAD DVT - NCLEX', false, 7, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "6 Ps arterial emergency" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "6 Ps arterial emergency" in PVD / PAD / DVT?', '[{"id": "a", "text": "6 Ps indicate stable chronic venous disease in this note."}, {"id": "b", "text": "Treat 6 Ps as limb-threatening emergency requiring immediate escalation."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "Intact endothelium is risk factor in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Acute arterial occlusion signs are pain, pallor, pulselessness, paresthesia, poikilothermia, and paralysis. Treat 6 Ps as limb-threatening emergency requiring immediate escalation.', 'PVD PAD DVT - NCLEX', false, 8, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Buerger-Allen test" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "Buerger-Allen test" in PVD / PAD / DVT?', '[{"id": "a", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "b", "text": "In Buerger-Allen test, leg elevation causing pallor then dependent rubor supports PAD."}, {"id": "c", "text": "No color change is required for positive test in this note."}, {"id": "d", "text": "Bilateral cool pale legs are hallmark DVT sign in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because In Buerger-Allen test, leg elevation causing pallor then dependent rubor supports PAD. Interpret positional color changes as arterial insufficiency evidence.', 'PVD PAD DVT - NCLEX', false, 9, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "PAD management essentials" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "PAD management essentials" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "Combine risk modification and perfusion restoration interventions."}, {"id": "b", "text": "Smoking has no effect on PAD outcomes in this note."}, {"id": "c", "text": "PAD legs should always be elevated high in this note."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["a"]'::jsonb, 'Correct because PAD management includes smoking cessation priority, antiplatelets, supervised walking, revascularization, and dependent leg positioning. Combine risk modification and perfusion restoration interventions.', 'PVD PAD DVT - NCLEX', false, 10, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "Virchow triad overview" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "Virchow triad overview" is most accurate?', '[{"id": "a", "text": "PE presents only with slow asymptomatic edema in this note."}, {"id": "b", "text": "DVT causes follow Virchow triad: stasis, hypercoagulability, and endothelial injury."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "Hypothermia is a Virchow component in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because DVT causes follow Virchow triad: stasis, hypercoagulability, and endothelial injury. Identify which triad component is present to target prevention.', 'PVD PAD DVT - NCLEX', false, 11, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Stasis examples" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "Stasis examples" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "Early mobilization plans reduce stasis-driven thrombosis risk."}, {"id": "b", "text": "Stasis is unrelated to DVT in this note."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "Frequent ambulation is stasis cause in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Stasis examples listed include immobility, long flights, and post-op state. Early mobilization plans reduce stasis-driven thrombosis risk.', 'PVD PAD DVT - NCLEX', false, 12, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Hypercoagulability examples" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "Hypercoagulability examples" in PVD / PAD / DVT?', '[{"id": "a", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "b", "text": "Cancer lowers DVT risk in this note."}, {"id": "c", "text": "Hypercoagulability risks listed include oral contraceptives, cancer, and clotting disorders."}, {"id": "d", "text": "Hypercoagulability excludes medication effects in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Hypercoagulability risks listed include oral contraceptives, cancer, and clotting disorders. Screen thrombosis history and prothrombotic exposures carefully.', 'PVD PAD DVT - NCLEX', false, 13, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Endothelial injury examples" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "Endothelial injury examples" in PVD / PAD / DVT?', '[{"id": "a", "text": "Protect vessel integrity and monitor post-procedural patients."}, {"id": "b", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "c", "text": "Intact endothelium is risk factor in this note."}, {"id": "d", "text": "Only diet causes endothelial injury in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Endothelial injury examples include trauma, surgery, and catheters. Protect vessel integrity and monitor post-procedural patients.', 'PVD PAD DVT - NCLEX', false, 14, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "DVT signs" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "DVT signs" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "DVT signs include unilateral calf pain/tenderness, unilateral edema, warmth, redness, and possible low-grade fever."}, {"id": "b", "text": "DVT typically causes absent pulses as first sign in this note."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}]'::jsonb, '["a"]'::jsonb, 'Correct because DVT signs include unilateral calf pain/tenderness, unilateral edema, warmth, redness, and possible low-grade fever. Unilateral inflammatory limb signs should trigger urgent DVT evaluation.', 'PVD PAD DVT - NCLEX', false, 15, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "Homans sign caution" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "Homans sign caution" is most accurate?', '[{"id": "a", "text": "Rely on modern diagnostics rather than outdated bedside signs."}, {"id": "b", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "c", "text": "Homans is mandatory for all exams in this note."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["a"]'::jsonb, 'Correct because Homans sign is noted as unreliable and rarely tested now. Rely on modern diagnostics rather than outdated bedside signs.', 'PVD PAD DVT - NCLEX', false, 16, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "PE deterioration clue" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "PE deterioration clue" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "DVT can embolize causing PE with sudden dyspnea, chest pain, hypoxia, and tachycardia."}, {"id": "b", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "c", "text": "PE presents only with slow asymptomatic edema in this note."}, {"id": "d", "text": "PE risk is absent after DVT diagnosis in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because DVT can embolize causing PE with sudden dyspnea, chest pain, hypoxia, and tachycardia. Sudden respiratory decline in DVT patient is emergency PE suspicion.', 'PVD PAD DVT - NCLEX', false, 17, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "DVT anticoagulation" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "DVT anticoagulation" in PVD / PAD / DVT?', '[{"id": "a", "text": "Massaging DVT leg is recommended to improve flow in this note."}, {"id": "b", "text": "Anticoagulation is limited to one day in this note."}, {"id": "c", "text": "Ensure transition from acute to maintenance anticoagulation safely."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["c"]'::jsonb, 'Correct because DVT treatment starts with heparin acutely then warfarin or NOAC for 3–6 months. Ensure transition from acute to maintenance anticoagulation safely.', 'PVD PAD DVT - NCLEX', false, 18, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "DVT supportive care" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "DVT supportive care" in PVD / PAD / DVT?', '[{"id": "a", "text": "Leg dependency is preferred for DVT edema in this note."}, {"id": "b", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "Supportive care includes leg elevation above heart, compression stockings, and early ambulation once anticoagulated."}]'::jsonb, '["d"]'::jsonb, 'Correct because Supportive care includes leg elevation above heart, compression stockings, and early ambulation once anticoagulated. Balance clot stabilization with circulation/mobility support.', 'PVD PAD DVT - NCLEX', false, 19, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "IVC filter indication" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "IVC filter indication" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "IVC filters are only for arterial occlusion in this note."}, {"id": "b", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "c", "text": "Use mechanical embolic protection when anticoagulation cannot be used."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["c"]'::jsonb, 'Correct because IVC filter is considered if anticoagulation is contraindicated. Use mechanical embolic protection when anticoagulation cannot be used.', 'PVD PAD DVT - NCLEX', false, 20, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "Arterial ulcer profile" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "Arterial ulcer profile" is most accurate?', '[{"id": "a", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "b", "text": "Arterial ulcers are warm moist and painless in this note."}, {"id": "c", "text": "DVT is primarily arterial plaque rupture in this note."}, {"id": "d", "text": "Arterial ulcers are on toes/lateral malleolus/foot, very painful, punched-out, pale/necrotic, with diminished/absent pulses and cool hairless skin."}]'::jsonb, '["d"]'::jsonb, 'Correct because Arterial ulcers are on toes/lateral malleolus/foot, very painful, punched-out, pale/necrotic, with diminished/absent pulses and cool hairless skin. Identify ischemic ulcer features to prevent limb loss.', 'PVD PAD DVT - NCLEX', false, 21, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Venous ulcer profile" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "Venous ulcer profile" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "b", "text": "Use venous profile to prioritize elevation and compression strategies."}, {"id": "c", "text": "Venous ulcers are lateral toe punched-out lesions in this note."}, {"id": "d", "text": "Absent pulses are hallmark venous insufficiency sign in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Venous ulcers are medial malleolus, irregular/ragged, granulating/ruddy, warm edematous skin with pulses present. Use venous profile to prioritize elevation and compression strategies.', 'PVD PAD DVT - NCLEX', false, 22, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Positioning contrast" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "Positioning contrast" in PVD / PAD / DVT?', '[{"id": "a", "text": "PAD requires leg elevation above heart in this note."}, {"id": "b", "text": "Arterial disease benefits from dependent legs, while venous disease benefits from elevation to reduce pooling."}, {"id": "c", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "d", "text": "Venous ulcers are punched-out lateral toe lesions in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Arterial disease benefits from dependent legs, while venous disease benefits from elevation to reduce pooling. Correct positioning is immediate, high-yield bedside intervention.', 'PVD PAD DVT - NCLEX', false, 23, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Key nursing NCLEX points" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "Key nursing NCLEX points" in PVD / PAD / DVT?', '[{"id": "a", "text": "Massaging DVT leg is recommended to improve flow in this note."}, {"id": "b", "text": "PAD pain improves with walking in this note."}, {"id": "c", "text": "Avoid embolization and identify limb-threatening ischemia rapidly."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["c"]'::jsonb, 'Correct because Do not massage suspected DVT leg, assess pulses pre/post interventions, prevent DVT with ambulation/compression/anticoagulation post-op, and treat 6 Ps as arterial emergency. Avoid embolization and identify limb-threatening ischemia rapidly.', 'PVD PAD DVT - NCLEX', false, 24, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "PVD umbrella concept" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "PVD umbrella concept" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "ABI is not used for PAD in this note."}, {"id": "b", "text": "PVD includes only pulmonary vessels in this note."}, {"id": "c", "text": "PVD excludes venous disease in this note."}, {"id": "d", "text": "Peripheral vascular disease is an umbrella term that includes arterial and/or venous disorders."}]'::jsonb, '["d"]'::jsonb, 'Correct because Peripheral vascular disease is an umbrella term that includes arterial and/or venous disorders. Differentiate arterial from venous findings before intervention.', 'PVD PAD DVT - NCLEX', false, 25, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "PAD definition" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "PAD definition" is most accurate?', '[{"id": "a", "text": "Recognize ischemic limb signs and perfusion threats early."}, {"id": "b", "text": "6 Ps indicate stable chronic venous disease in this note."}, {"id": "c", "text": "PAD is venous valve failure in this note."}, {"id": "d", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}]'::jsonb, '["a"]'::jsonb, 'Correct because Peripheral arterial disease is arterial narrowing from atherosclerosis causing reduced blood flow. Recognize ischemic limb signs and perfusion threats early.', 'PVD PAD DVT - NCLEX', false, 26, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "DVT definition" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "DVT definition" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "No color change is required for positive test in this note."}, {"id": "b", "text": "DVT is primarily arterial plaque rupture in this note."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "Deep vein thrombosis is thrombus formation in deep veins, usually leg, with pulmonary embolism risk."}]'::jsonb, '["d"]'::jsonb, 'Correct because Deep vein thrombosis is thrombus formation in deep veins, usually leg, with pulmonary embolism risk. Prevent embolization and monitor for PE deterioration.', 'PVD PAD DVT - NCLEX', false, 27, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Venous insufficiency signs" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "Venous insufficiency signs" in PVD / PAD / DVT?', '[{"id": "a", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "b", "text": "Smoking has no effect on PAD outcomes in this note."}, {"id": "c", "text": "Absent pulses are hallmark venous insufficiency sign in this note."}, {"id": "d", "text": "Use skin temperature/pulse pattern to separate venous from arterial disease."}]'::jsonb, '["d"]'::jsonb, 'Correct because Venous insufficiency signs include varicosities, edema, brown hemosiderin skin changes, warm moist skin, and pulses present. Use skin temperature/pulse pattern to separate venous from arterial disease.', 'PVD PAD DVT - NCLEX', false, 28, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "Venous stasis ulcer profile" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "Venous stasis ulcer profile" in PVD / PAD / DVT?', '[{"id": "a", "text": "Venous ulcers are always severe pain in this note."}, {"id": "b", "text": "Venous ulcers are punched-out lateral toe lesions in this note."}, {"id": "c", "text": "Virchow triad applies only to arterial disease in this note."}, {"id": "d", "text": "Venous ulcers are usually at medial malleolus, irregular edges, and often painless."}]'::jsonb, '["d"]'::jsonb, 'Correct because Venous ulcers are usually at medial malleolus, irregular edges, and often painless. Correct ulcer classification guides positioning and wound strategy.', 'PVD PAD DVT - NCLEX', false, 29, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "PAD symptom hallmark" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "PAD symptom hallmark" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "Progression from exertional pain to rest pain signals worsening ischemia."}, {"id": "b", "text": "PAD never causes rest pain in this note."}, {"id": "c", "text": "PAD pain improves with walking in this note."}, {"id": "d", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}]'::jsonb, '["a"]'::jsonb, 'Correct because Intermittent claudication is leg pain with walking relieved by rest; advanced disease may cause rest pain. Progression from exertional pain to rest pain signals worsening ischemia.', 'PVD PAD DVT - NCLEX', false, 30, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "ABI threshold" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "ABI threshold" is most accurate?', '[{"id": "a", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "b", "text": "Hypercoagulability excludes medication effects in this note."}, {"id": "c", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "d", "text": "Ankle-brachial index below 0.9 supports PAD diagnosis."}]'::jsonb, '["d"]'::jsonb, 'Correct because Ankle-brachial index below 0.9 supports PAD diagnosis. Use ABI to quantify arterial perfusion deficit objectively.', 'PVD PAD DVT - NCLEX', false, 31, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "6 Ps arterial emergency" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "6 Ps arterial emergency" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "Only diet causes endothelial injury in this note."}, {"id": "b", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "c", "text": "Treat 6 Ps as limb-threatening emergency requiring immediate escalation."}, {"id": "d", "text": "6 Ps indicate stable chronic venous disease in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Acute arterial occlusion signs are pain, pallor, pulselessness, paresthesia, poikilothermia, and paralysis. Treat 6 Ps as limb-threatening emergency requiring immediate escalation.', 'PVD PAD DVT - NCLEX', false, 32, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Buerger-Allen test" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "Buerger-Allen test" in PVD / PAD / DVT?', '[{"id": "a", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "b", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "c", "text": "No color change is required for positive test in this note."}, {"id": "d", "text": "In Buerger-Allen test, leg elevation causing pallor then dependent rubor supports PAD."}]'::jsonb, '["d"]'::jsonb, 'Correct because In Buerger-Allen test, leg elevation causing pallor then dependent rubor supports PAD. Interpret positional color changes as arterial insufficiency evidence.', 'PVD PAD DVT - NCLEX', false, 33, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "PAD management essentials" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "PAD management essentials" in PVD / PAD / DVT?', '[{"id": "a", "text": "Combine risk modification and perfusion restoration interventions."}, {"id": "b", "text": "Smoking has no effect on PAD outcomes in this note."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "PAD legs should always be elevated high in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because PAD management includes smoking cessation priority, antiplatelets, supervised walking, revascularization, and dependent leg positioning. Combine risk modification and perfusion restoration interventions.', 'PVD PAD DVT - NCLEX', false, 34, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Virchow triad overview" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "Virchow triad overview" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "Hypothermia is a Virchow component in this note."}, {"id": "b", "text": "DVT causes follow Virchow triad: stasis, hypercoagulability, and endothelial injury."}, {"id": "c", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["b"]'::jsonb, 'Correct because DVT causes follow Virchow triad: stasis, hypercoagulability, and endothelial injury. Identify which triad component is present to target prevention.', 'PVD PAD DVT - NCLEX', false, 35, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "Stasis examples" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "Stasis examples" is most accurate?', '[{"id": "a", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "b", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "c", "text": "Stasis is unrelated to DVT in this note."}, {"id": "d", "text": "Early mobilization plans reduce stasis-driven thrombosis risk."}]'::jsonb, '["d"]'::jsonb, 'Correct because Stasis examples listed include immobility, long flights, and post-op state. Early mobilization plans reduce stasis-driven thrombosis risk.', 'PVD PAD DVT - NCLEX', false, 36, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Hypercoagulability examples" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "Hypercoagulability examples" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "Leg dependency is preferred for DVT edema in this note."}, {"id": "b", "text": "Hypercoagulability risks listed include oral contraceptives, cancer, and clotting disorders."}, {"id": "c", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "d", "text": "Cancer lowers DVT risk in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Hypercoagulability risks listed include oral contraceptives, cancer, and clotting disorders. Screen thrombosis history and prothrombotic exposures carefully.', 'PVD PAD DVT - NCLEX', false, 37, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Endothelial injury examples" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "Endothelial injury examples" in PVD / PAD / DVT?', '[{"id": "a", "text": "Intact endothelium is risk factor in this note."}, {"id": "b", "text": "Only diet causes endothelial injury in this note."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "Protect vessel integrity and monitor post-procedural patients."}]'::jsonb, '["d"]'::jsonb, 'Correct because Endothelial injury examples include trauma, surgery, and catheters. Protect vessel integrity and monitor post-procedural patients.', 'PVD PAD DVT - NCLEX', false, 38, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "DVT signs" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "DVT signs" in PVD / PAD / DVT?', '[{"id": "a", "text": "DVT signs include unilateral calf pain/tenderness, unilateral edema, warmth, redness, and possible low-grade fever."}, {"id": "b", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "c", "text": "Bilateral cool pale legs are hallmark DVT sign in this note."}, {"id": "d", "text": "DVT typically causes absent pulses as first sign in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because DVT signs include unilateral calf pain/tenderness, unilateral edema, warmth, redness, and possible low-grade fever. Unilateral inflammatory limb signs should trigger urgent DVT evaluation.', 'PVD PAD DVT - NCLEX', false, 39, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Homans sign caution" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "Homans sign caution" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "Homans is mandatory for all exams in this note."}, {"id": "b", "text": "Venous ulcers are lateral toe punched-out lesions in this note."}, {"id": "c", "text": "Rely on modern diagnostics rather than outdated bedside signs."}, {"id": "d", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}]'::jsonb, '["c"]'::jsonb, 'Correct because Homans sign is noted as unreliable and rarely tested now. Rely on modern diagnostics rather than outdated bedside signs.', 'PVD PAD DVT - NCLEX', false, 40, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "PE deterioration clue" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "PE deterioration clue" is most accurate?', '[{"id": "a", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "b", "text": "DVT can embolize causing PE with sudden dyspnea, chest pain, hypoxia, and tachycardia."}, {"id": "c", "text": "PE presents only with slow asymptomatic edema in this note."}, {"id": "d", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}]'::jsonb, '["b"]'::jsonb, 'Correct because DVT can embolize causing PE with sudden dyspnea, chest pain, hypoxia, and tachycardia. Sudden respiratory decline in DVT patient is emergency PE suspicion.', 'PVD PAD DVT - NCLEX', false, 41, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "DVT anticoagulation" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "DVT anticoagulation" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "Ensure transition from acute to maintenance anticoagulation safely."}, {"id": "b", "text": "6 Ps can be observed without escalation in this note."}, {"id": "c", "text": "DVT is treated with antiplatelet only in this note."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["a"]'::jsonb, 'Correct because DVT treatment starts with heparin acutely then warfarin or NOAC for 3–6 months. Ensure transition from acute to maintenance anticoagulation safely.', 'PVD PAD DVT - NCLEX', false, 42, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "DVT supportive care" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "DVT supportive care" in PVD / PAD / DVT?', '[{"id": "a", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "b", "text": "Supportive care includes leg elevation above heart, compression stockings, and early ambulation once anticoagulated."}, {"id": "c", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "d", "text": "Leg dependency is preferred for DVT edema in this note."}]'::jsonb, '["b"]'::jsonb, 'Correct because Supportive care includes leg elevation above heart, compression stockings, and early ambulation once anticoagulated. Balance clot stabilization with circulation/mobility support.', 'PVD PAD DVT - NCLEX', false, 43, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "IVC filter indication" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "IVC filter indication" in PVD / PAD / DVT?', '[{"id": "a", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "b", "text": "Use mechanical embolic protection when anticoagulation cannot be used."}, {"id": "c", "text": "IVC filters are only for arterial occlusion in this note."}, {"id": "d", "text": "Pulses do not need reassessment after vascular interventions."}]'::jsonb, '["b"]'::jsonb, 'Correct because IVC filter is considered if anticoagulation is contraindicated. Use mechanical embolic protection when anticoagulation cannot be used.', 'PVD PAD DVT - NCLEX', false, 44, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "Arterial ulcer profile" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "Arterial ulcer profile" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "Arterial ulcers are warm moist and painless in this note."}, {"id": "b", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "c", "text": "DVT has no embolic risk in this note."}, {"id": "d", "text": "Arterial ulcers are on toes/lateral malleolus/foot, very painful, punched-out, pale/necrotic, with diminished/absent pulses and cool hairless skin."}]'::jsonb, '["d"]'::jsonb, 'Correct because Arterial ulcers are on toes/lateral malleolus/foot, very painful, punched-out, pale/necrotic, with diminished/absent pulses and cool hairless skin. Identify ischemic ulcer features to prevent limb loss.', 'PVD PAD DVT - NCLEX', false, 45, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'According to the PVD / PAD / DVT note, which statement about "Venous ulcer profile" is most accurate?', 'According to the PVD / PAD / DVT note, which statement about "Venous ulcer profile" is most accurate?', '[{"id": "a", "text": "Venous ulcers are lateral toe punched-out lesions in this note."}, {"id": "b", "text": "Venous ulcers have absent pulses and pale necrotic bed in this note."}, {"id": "c", "text": "Use venous profile to prioritize elevation and compression strategies."}, {"id": "d", "text": "Cool hairless skin is classic venous profile in this note."}]'::jsonb, '["c"]'::jsonb, 'Correct because Venous ulcers are medial malleolus, irregular/ragged, granulating/ruddy, warm edematous skin with pulses present. Use venous profile to prioritize elevation and compression strategies.', 'PVD PAD DVT - NCLEX', false, 46, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is reviewing "Positioning contrast" in PVD / PAD / DVT. Which statement is correct?', 'The nurse is reviewing "Positioning contrast" in PVD / PAD / DVT. Which statement is correct?', '[{"id": "a", "text": "Arterial disease benefits from dependent legs, while venous disease benefits from elevation to reduce pooling."}, {"id": "b", "text": "Venous ulcers are always severe pain in this note."}, {"id": "c", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "d", "text": "PAD requires leg elevation above heart in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Arterial disease benefits from dependent legs, while venous disease benefits from elevation to reduce pooling. Correct positioning is immediate, high-yield bedside intervention.', 'PVD PAD DVT - NCLEX', false, 47, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which clinical judgment is most accurate regarding "Key nursing NCLEX points" in PVD / PAD / DVT?', 'Which clinical judgment is most accurate regarding "Key nursing NCLEX points" in PVD / PAD / DVT?', '[{"id": "a", "text": "Avoid embolization and identify limb-threatening ischemia rapidly."}, {"id": "b", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "c", "text": "6 Ps can be observed without escalation in this note."}, {"id": "d", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}]'::jsonb, '["a"]'::jsonb, 'Correct because Do not massage suspected DVT leg, assess pulses pre/post interventions, prevent DVT with ambulation/compression/anticoagulation post-op, and treat 6 Ps as arterial emergency. Avoid embolization and identify limb-threatening ischemia rapidly.', 'PVD PAD DVT - NCLEX', false, 48, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'In rapid prioritization, which statement is most consistent with "PVD umbrella concept" in PVD / PAD / DVT?', 'In rapid prioritization, which statement is most consistent with "PVD umbrella concept" in PVD / PAD / DVT?', '[{"id": "a", "text": "Pulses do not need reassessment after vascular interventions."}, {"id": "b", "text": "PVD excludes venous disease in this note."}, {"id": "c", "text": "PVD includes only pulmonary vessels in this note."}, {"id": "d", "text": "Peripheral vascular disease is an umbrella term that includes arterial and/or venous disorders."}]'::jsonb, '["d"]'::jsonb, 'Correct because Peripheral vascular disease is an umbrella term that includes arterial and/or venous disorders. Differentiate arterial from venous findings before intervention.', 'PVD PAD DVT - NCLEX', false, 49, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which conclusion about "PAD definition" in PVD / PAD / DVT would the nurse recognize as correct?', 'Which conclusion about "PAD definition" in PVD / PAD / DVT would the nurse recognize as correct?', '[{"id": "a", "text": "Recognize ischemic limb signs and perfusion threats early."}, {"id": "b", "text": "Pitting edema replaces pulselessness in 6 Ps in this note."}, {"id": "c", "text": "Immediate escalation is unnecessary unless bilateral symptoms are present."}, {"id": "d", "text": "PAD is venous valve failure in this note."}]'::jsonb, '["a"]'::jsonb, 'Correct because Peripheral arterial disease is arterial narrowing from atherosclerosis causing reduced blood flow. Recognize ischemic limb signs and perfusion threats early.', 'PVD PAD DVT - NCLEX', false, 50, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'Which statements about "PVD umbrella concept" in PVD / PAD / DVT are correct? (Select all that apply)', 'Which statements about "PVD umbrella concept" in PVD / PAD / DVT are correct? (Select all that apply)', '[{"id": "a", "text": "Venous disease can also fall under PVD."}, {"id": "b", "text": "PAD is within broader PVD category."}, {"id": "c", "text": "PVD excludes venous disease in this note."}, {"id": "d", "text": "PVD can involve arteries and veins."}, {"id": "e", "text": "PVD includes only pulmonary vessels in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Peripheral vascular disease is an umbrella term that includes arterial and/or venous disorders.', 'PVD PAD DVT - NCLEX', true, 51, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'For PVD / PAD / DVT, which findings or actions relate to "PAD definition"? (Select all that apply)', 'For PVD / PAD / DVT, which findings or actions relate to "PAD definition"? (Select all that apply)', '[{"id": "a", "text": "Atherosclerosis is core mechanism in PAD."}, {"id": "b", "text": "Reduced distal flow causes ischemic symptoms."}, {"id": "c", "text": "PAD is caused by pulmonary emboli in this note."}, {"id": "d", "text": "PAD is arterial only in this note."}, {"id": "e", "text": "PAD is venous valve failure in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Peripheral arterial disease is arterial narrowing from atherosclerosis causing reduced blood flow.', 'PVD PAD DVT - NCLEX', true, 52, 1, true);
  INSERT INTO test_questions (test_id, topic_id, question, question_stem, options, correct_answer, rationale, category, is_multiple_choice, display_order, points, is_active)
  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "DVT definition" in PVD / PAD / DVT? (Select all that apply)', 'The nurse is planning care. Which items apply to "DVT definition" in PVD / PAD / DVT? (Select all that apply)', '[{"id": "a", "text": "DVT is venous clot disease."}, {"id": "b", "text": "DVT is primarily arterial plaque rupture in this note."}, {"id": "c", "text": "Thrombus embolization can cause PE."}, {"id": "d", "text": "DVT has no embolic risk in this note."}, {"id": "e", "text": "DVT usually occurs in deep leg veins."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Deep vein thrombosis is thrombus formation in deep veins, usually leg, with pulmonary embolism risk.', 'PVD PAD DVT - NCLEX', true, 53, 1, true);
