  VALUES (v_test_id, v_topic_id, 'During reassessment, which observations align with "Venous stasis ulcer profile" in PVD / PAD / DVT? (Select all that apply)', 'During reassessment, which observations align with "Venous stasis ulcer profile" in PVD / PAD / DVT? (Select all that apply)', '[{"id": "a", "text": "Medial malleolus location suggests venous ulcer."}, {"id": "b", "text": "Venous ulcers are always severe pain in this note."}, {"id": "c", "text": "Venous ulcers are punched-out lateral toe lesions in this note."}, {"id": "d", "text": "Venous ulcer pain is often mild or absent."}, {"id": "e", "text": "Venous ulcer edges are irregular/ragged."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: Venous ulcers are usually at medial malleolus, irregular edges, and often painless.', 'PVD PAD DVT - NCLEX', true, 55, 1, true);
