  VALUES (v_test_id, v_topic_id, 'Which statements about "PAD symptom hallmark" in PVD / PAD / DVT are correct? (Select all that apply)', 'Which statements about "PAD symptom hallmark" in PVD / PAD / DVT are correct? (Select all that apply)', '[{"id": "a", "text": "Rest relieves claudication in earlier PAD."}, {"id": "b", "text": "PAD never causes rest pain in this note."}, {"id": "c", "text": "Rest pain indicates advanced disease in note."}, {"id": "d", "text": "Claudication appears with activity in PAD."}, {"id": "e", "text": "PAD pain improves with walking in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Intermittent claudication is leg pain with walking relieved by rest; advanced disease may cause rest pain.', 'PVD PAD DVT - NCLEX', true, 56, 1, true);
