  VALUES (v_test_id, v_topic_id, 'For PVD / PAD / DVT, which findings or actions relate to "PE deterioration clue"? (Select all that apply)', 'For PVD / PAD / DVT, which findings or actions relate to "PE deterioration clue"? (Select all that apply)', '[{"id": "a", "text": "Embolization risk is central DVT danger."}, {"id": "b", "text": "PE risk is absent after DVT diagnosis in this note."}, {"id": "c", "text": "Chest pain/hypoxia/tachycardia are PE clues."}, {"id": "d", "text": "Sudden dyspnea can indicate PE in DVT patient."}, {"id": "e", "text": "PE presents only with slow asymptomatic edema in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: DVT can embolize causing PE with sudden dyspnea, chest pain, hypoxia, and tachycardia.', 'PVD PAD DVT - NCLEX', true, 67, 1, true);
