  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "DVT anticoagulation" in PVD / PAD / DVT? (Select all that apply)', 'The nurse is planning care. Which items apply to "DVT anticoagulation" in PVD / PAD / DVT? (Select all that apply)', '[{"id": "a", "text": "Duration listed is about 3–6 months."}, {"id": "b", "text": "Anticoagulation is limited to one day in this note."}, {"id": "c", "text": "Warfarin/NOAC are long-term options."}, {"id": "d", "text": "Heparin is acute DVT treatment in note."}, {"id": "e", "text": "DVT is treated with antiplatelet only in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: DVT treatment starts with heparin acutely then warfarin or NOAC for 3–6 months.', 'PVD PAD DVT - NCLEX', true, 68, 1, true);
