  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "Positioning contrast" in PVD / PAD / DVT? (Select all that apply)', 'The nurse is planning care. Which items apply to "Positioning contrast" in PVD / PAD / DVT? (Select all that apply)', '[{"id": "a", "text": "PAD legs dependent improves arterial flow in note."}, {"id": "b", "text": "PAD requires leg elevation above heart in this note."}, {"id": "c", "text": "Positioning differs by arterial vs venous pathology."}, {"id": "d", "text": "Both arterial and venous disease require identical positioning in this note."}, {"id": "e", "text": "Venous insufficiency legs elevated helps pooling."}]'::jsonb, '["a", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Arterial disease benefits from dependent legs, while venous disease benefits from elevation to reduce pooling.', 'PVD PAD DVT - NCLEX', true, 73, 1, true);
