  VALUES (v_test_id, v_topic_id, 'Which of the following are consistent with "Key nursing NCLEX points" in PVD / PAD / DVT? (Select all that apply)', 'Which of the following are consistent with "Key nursing NCLEX points" in PVD / PAD / DVT? (Select all that apply)', '[{"id": "a", "text": "Massaging DVT leg is recommended to improve flow in this note."}, {"id": "b", "text": "6 Ps require immediate provider notification."}, {"id": "c", "text": "Never massage suspected DVT limb."}, {"id": "d", "text": "6 Ps can be observed without escalation in this note."}, {"id": "e", "text": "Pulse assessment before/after intervention is emphasized."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: Do not massage suspected DVT leg, assess pulses pre/post interventions, prevent DVT with ambulation/compression/anticoagulation post-op, and treat 6 Ps as arterial emergency.', 'PVD PAD DVT - NCLEX', true, 74, 1, true);
