  VALUES (v_test_id, v_topic_id, 'Which statements about "PAD definition" in PVD / PAD / DVT are correct? (Select all that apply)', 'Which statements about "PAD definition" in PVD / PAD / DVT are correct? (Select all that apply)', '[{"id": "a", "text": "Atherosclerosis is core mechanism in PAD."}, {"id": "b", "text": "PAD is venous valve failure in this note."}, {"id": "c", "text": "Reduced distal flow causes ischemic symptoms."}, {"id": "d", "text": "PAD is arterial only in this note."}, {"id": "e", "text": "PAD is caused by pulmonary emboli in this note."}]'::jsonb, '["a", "c", "d"]'::jsonb, 'Correct selections align with note-based facts: Peripheral arterial disease is arterial narrowing from atherosclerosis causing reduced blood flow.', 'PVD PAD DVT - NCLEX', true, 76, 1, true);
