  VALUES (v_test_id, v_topic_id, 'Which statements about "PE deterioration clue" in PVD / PAD / DVT are correct? (Select all that apply)', 'Which statements about "PE deterioration clue" in PVD / PAD / DVT are correct? (Select all that apply)', '[{"id": "a", "text": "PE presents only with slow asymptomatic edema in this note."}, {"id": "b", "text": "Sudden dyspnea can indicate PE in DVT patient."}, {"id": "c", "text": "Chest pain/hypoxia/tachycardia are PE clues."}, {"id": "d", "text": "PE risk is absent after DVT diagnosis in this note."}, {"id": "e", "text": "Embolization risk is central DVT danger."}]'::jsonb, '["b", "c", "e"]'::jsonb, 'Correct selections align with note-based facts: DVT can embolize causing PE with sudden dyspnea, chest pain, hypoxia, and tachycardia.', 'PVD PAD DVT - NCLEX', true, 91, 1, true);
