  VALUES (v_test_id, v_topic_id, 'For PVD / PAD / DVT, which findings or actions relate to "DVT anticoagulation"? (Select all that apply)', 'For PVD / PAD / DVT, which findings or actions relate to "DVT anticoagulation"? (Select all that apply)', '[{"id": "a", "text": "Duration listed is about 3–6 months."}, {"id": "b", "text": "Anticoagulation is limited to one day in this note."}, {"id": "c", "text": "DVT is treated with antiplatelet only in this note."}, {"id": "d", "text": "Warfarin/NOAC are long-term options."}, {"id": "e", "text": "Heparin is acute DVT treatment in note."}]'::jsonb, '["a", "d", "e"]'::jsonb, 'Correct selections align with note-based facts: DVT treatment starts with heparin acutely then warfarin or NOAC for 3–6 months.', 'PVD PAD DVT - NCLEX', true, 92, 1, true);
