  VALUES (v_test_id, v_topic_id, 'The nurse is planning care. Which items apply to "DVT supportive care" in PVD / PAD / DVT? (Select all that apply)', 'The nurse is planning care. Which items apply to "DVT supportive care" in PVD / PAD / DVT? (Select all that apply)', '[{"id": "a", "text": "Leg elevation above heart is listed."}, {"id": "b", "text": "Early ambulation is advised after anticoagulation."}, {"id": "c", "text": "Leg dependency is preferred for DVT edema in this note."}, {"id": "d", "text": "Compression stockings are listed."}, {"id": "e", "text": "Strict indefinite bed rest is required in this note."}]'::jsonb, '["a", "b", "d"]'::jsonb, 'Correct selections align with note-based facts: Supportive care includes leg elevation above heart, compression stockings, and early ambulation once anticoagulated.', 'PVD PAD DVT - NCLEX', true, 93, 1, true);
